from typing import List, Tuple


def satir_farki(a: List[str], b: List[str]) -> List[Tuple[str, str]]:
    """
    a listesini b'ye çeviren minimal düzenleme dizisi döndürür.
    - " " ve "-" olanlar sırayla a'yı, " " ve "+" olanlar sırayla b'yı vermeli.
    - Ortak (" ") satır sayısı mümkün olan en fazla olmalı (en uzun ortak alt dizi).
    - Ardışık değişikliklerde silmeler eklemelerden önce gelsin.
    """
    m, n = len(a), len(b)
    lcs = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                lcs[i][j] = lcs[i - 1][j - 1] + 1
            else:
                lcs[i][j] = max(lcs[i - 1][j], lcs[i][j - 1])
    match_positions = []
    i, j = m, n
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1] and lcs[i][j] == lcs[i - 1][j - 1] + 1:
            match_positions.append((i - 1, j - 1))
            i -= 1
            j -= 1
        elif lcs[i - 1][j] >= lcs[i][j - 1]:
            i -= 1
        else:
            j -= 1
    match_positions.reverse()
    match_set = set(match_positions)
    a_matches = {i for i, j in match_set}
    b_matches = {j for i, j in match_set}
    common = a_matches & b_matches
    only_a = a_matches - common
    only_b = b_matches - common
    result = []
    i = 0
    for mi in sorted(a_matches):
        if mi in common:
            result.append((" ", a[mi]))
        else:
            result.append(("-", a[mi]))
    j = 0
    for mj in sorted(only_b):
        result.append(("+", b[mj]))
    return result

